$check($replay->get_status()===200 && !isset($replay->get_data()['token']) && strpos(wp_json_encode($listed->get_data()),$invite['token'])===false && strpos(wp_json_encode($listed->get_data()),'token_hash')===false,'creation replay and list never reveal token or token hash');
