wp_set_current_user($wrong);
$check($call('POST','/invitations/accept',array('token'=>$invite['token']))->get_status()===404,'possession of token cannot bind a different signed-in email');
wp_set_current_user($invited); $wpdb->update(DB::table('memberships'),array('status'=>'revoked'),array('org_id'=>$orgA,'user_id'=>$manager));
$check($call('POST','/invitations/accept',array('token'=>$invite['token']))->get_status()===404,'revoked inviter cannot confer pending access');
$wpdb->update(DB::table('memberships'),array('status'=>'active'),array('org_id'=>$orgA,'user_id'=>$manager));
$accepted=$call('POST','/invitations/accept',array('token'=>$invite['token']));
$check($accepted->get_status()===200 && Auth::member_role($orgA)==='viewer' && current_user_can('atlas_manage_records'),'matched authenticated recipient explicitly activates scoped membership and capability ceiling');
$check(($accepted->get_data()['capability_setup']??'')==='ready' && !empty(get_user_meta($invited,wp_get_current_user()->cap_key,true)['atlas_manage_records']),'activation updates both persisted capabilities and the current request capability map');
$check($call('POST','/invitations/accept',array('token'=>$invite['token']))->get_status()===404,'accepted token is single-use');
$acceptEvents=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('audit').' WHERE action=%s AND object_id=%s','partner.invitation_accept',$invite['id']));
$check($acceptEvents===1,'one invitation activation has one audit record');
wp_set_current_user($manager);
$check($call('POST',$base.'/invitations',$inviteBody,'member_exists_'.$suffix)->get_status()===409,'invitation cannot overwrite an existing membership');
$revokeBody=array('email'=>get_userdata($wrong)->user_email,'role'=>'viewer','expires_in_hours'=>24);
$revoked=$call('POST',$base.'/invitations',$revokeBody,'revoke_'.$suffix)->get_data();
$check($call('POST',$base.'/invitations/'.$revoked['id'].'/revoke',array('reason'=>'Fictional staff change'))->get_status()===200,'authorized invitation revocation persists a reason');
wp_set_current_user($wrong);
$check($call('POST','/invitations/accept',array('token'=>$revoked['token']))->get_status()===404,'revoked invitation cannot be accepted');
wp_set_current_user($manager); $expiry=$call('POST',$base.'/invitations',array('email'=>get_userdata($expired)->user_email,'role'=>'viewer','expires_in_hours'=>1),'expiry_'.$suffix)->get_data();
DB::set_test_now(str_replace(' ','T',$expiry['expires_at']).'Z'); wp_set_current_user($expired);
$check($call('POST','/invitations/accept',array('token'=>$expiry['token']))->get_status()===404 && !$wpdb->get_var($wpdb->prepare('SELECT user_id FROM '.DB::table('memberships').' WHERE org_id=%d AND user_id=%d',$orgA,$expired)),'invitation expires exactly at server deadline without activating membership');
DB::set_test_now('2027-06-01T06:00:00.000000Z'); wp_set_current_user($manager);
$faultInvite=$call('POST',$base.'/invitations',array('email'=>get_userdata($fault)->user_email,'role'=>'viewer','expires_in_hours'=>24),'fault_'.$suffix)->get_data();
wp_set_current_user($fault); DB::set_test_audit_failure(true);
try { $denied=$call('POST','/invitations/accept',array('token'=>$faultInvite['token'])); } finally { DB::set_test_audit_failure(false); }
$faultState=$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Atlas_Partner_Invitations::table().' WHERE id=%s',$faultInvite['id']));
$check($denied->get_status()===503 && $faultState==='pending' && !Auth::member($orgA,$fault),'audit failure rolls back invitation consumption and membership together');
$managerAccount=get_userdata($manager); $managerAccount->remove_cap('atlas_manage_offers');
$check($call('POST','/invitations/accept',array('token'=>$faultInvite['token']))->get_status()===404 && !Auth::member($orgA,$fault),'inviter capability revocation invalidates a pending capability grant');
wp_set_current_user($manager);
$limitedInvite=$call('POST',$base.'/invitations',array('email'=>get_userdata($limited)->user_email,'role'=>'contributor','expires_in_hours'=>24),'limited_'.$suffix)->get_data();
$managerAccount->add_cap('atlas_manage_offers'); wp_set_current_user($limited);
$limitedAccept=$call('POST','/invitations/accept',array('token'=>$limitedInvite['token']));
$check($limitedAccept->get_status()===200 && current_user_can('atlas_manage_records') && !current_user_can('atlas_manage_offers'),'invitation grants only capabilities captured from its creator, without later broadening');
