$check(current_user_can('atlas_manage_records') && !current_user_can('atlas_manage_offers'),'captured capability ceiling survives a fresh current-user instance');

// All terms are fictional; no provider, signature, email or real agreement is produced.
$terms=array('agency_party'=>'Fictional agency','partner_party'=>'Fictional partner','territories'=>'Fictional test region','pricing_terms'=>'Fictional fixed test terms; tax and calculation basis require legal/finance review.','settlement_terms'=>'Fictional monthly review, no transfer.','cancellation_terms'=>'Fictional cancellation review.','termination_terms'=>'Fictional notice review.','dispute_terms'=>'Fictional manual dispute review.','marketing_claims'=>'No verified legal or supplier claims.','effective_from'=>'2027-06-01T00:00:00Z','effective_until'=>'2027-07-01T00:00:00Z','services'=>array('event'),'confidential'=>true);
wp_set_current_user($admin); $contractKey='contract_'.$suffix; $create=$call('POST',$base.'/contracts',array('title'=>'Fictional agreement '.$suffix,'snapshot'=>$terms),$contractKey); $contract=$create->get_data();
