$revise=$call('POST',$path.'/versions',array('expected_version'=>1,'snapshot'=>$revisedTerms,'reason'=>'Fictional counterproposal'),'revision_'.$suffix);
$check($revise->get_status()===200 && $revise->get_data()['revision']===2 && $revise->get_data()['version']===2,'scoped manager negotiates by appending a new version');
$check($call('GET','/organizations/'.$orgB.'/contracts/'.$contract['id'])->get_status()===404,'cross-organization contract identifier discloses no terms');
wp_set_current_user($admin);
$check($call('POST',$path.'/review',$review,'stale_review_'.$suffix)->get_status()===409,'stale contract review cannot approve a newer snapshot');
$review['expected_version']=2; $approved=$call('POST',$path.'/review',$review,'review_'.$suffix);
$check($approved->get_status()===200 && $approved->get_data()['version']===3,'independent agency review approves the current negotiated version');
wp_set_current_user($manager); $detail=$call('GET',$path)->get_data(); $snapshot=$detail['versions'][0];
$accept=array('expected_version'=>3,'snapshot_hash'=>str_repeat('0',64),'authority_attested'=>true);
$check($call('POST',$path.'/accept',$accept,'wrong_hash_'.$suffix)->get_status()===409,'partner must accept the exact approved snapshot hash');
$accept['snapshot_hash']=$snapshot['snapshot_hash']; wp_set_current_user($invited);
$check($call('POST',$path.'/accept',$accept,'viewer_accept_'.$suffix)->get_status()===404,'read-only invited member cannot accept confidential contract terms');
wp_set_current_user($manager); $acceptKey='accept_'.$suffix; $signed=$call('POST',$path.'/accept',$accept,$acceptKey);
$check($signed->get_status()===200 && $signed->get_data()['state']==='accepted' && Atlas_Partner_Contracts::has_active_contract($orgA,'event'),'explicit partner attestation activates reviewed terms without claiming a legal signature');
$check($call('POST',$path.'/accept',$accept,$acceptKey)->get_status()===200,'same contract acceptance request has one effect');
$snapshotBefore=$wpdb->get_var($wpdb->prepare('SELECT snapshot FROM '.Atlas_Partner_Contracts::table(true).' WHERE contract_id=%s AND revision=2',$contract['id']));
$nextTerms=$revisedTerms; $nextTerms['services']=array('tour'); $nextTerms['effective_until']='2027-06-10T00:00:00Z';
$next=$call('POST',$path.'/versions',array('expected_version'=>4,'snapshot'=>$nextTerms,'reason'=>'Fictional amendment'),'amend_'.$suffix);
$check($next->get_status()===200 && Atlas_Partner_Contracts::has_active_contract($orgA,'event') && $snapshotBefore===$wpdb->get_var($wpdb->prepare('SELECT snapshot FROM '.Atlas_Partner_Contracts::table(true).' WHERE contract_id=%s AND revision=2',$contract['id'])),'amendment preserves accepted snapshot and existing valid service obligations');
wp_set_current_user($admin); $review['expected_version']=5;
$check($call('POST',$path.'/review',$review,'amend_review_'.$suffix)->get_status()===200,'agency independently reviews amendment');
wp_set_current_user($manager); $detail=$call('GET',$path)->get_data(); $accept['expected_version']=6; $accept['snapshot_hash']=$detail['versions'][0]['snapshot_hash'];
$check($call('POST',$path.'/accept',$accept,'amend_accept_'.$suffix)->get_status()===200 && !Atlas_Partner_Contracts::has_active_contract($orgA,'event') && Atlas_Partner_Contracts::has_active_contract($orgA,'tour'),'latest accepted amendment supersedes old service scope');
DB::set_test_now('2027-06-10T00:00:00.000000Z');
$check(!Atlas_Partner_Contracts::has_active_contract($orgA,'tour') && !Atlas_Partner_Contracts::has_active_contract($orgA,'event'),'expired latest acceptance cannot fall back to an older unexpired version');
DB::set_test_now('2027-06-01T06:00:00.000000Z'); wp_set_current_user($admin);
$check($call('POST',$path.'/close',array('expected_version'=>7,'reason'=>'Fictional closure'),'close_'.$suffix)->get_status()===200 && !Atlas_Partner_Contracts::has_active_contract($orgA,'tour'),'closing contract blocks new commitments and retains accepted history');
$before=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.Atlas_Partner_Contracts::table()); DB::set_test_audit_failure(true);
try { $auditFailed=$call('POST',$base.'/contracts',array('title'=>'Rollback fixture','snapshot'=>$terms),'contract_fault_'.$suffix); } finally { DB::set_test_audit_failure(false); }
