$_GET['lang']='en';
$check(strpos(Atlas_Partner_Invitations::panel(true),'Accept invitation')!==false && strpos(Atlas_Partner_Contracts::panel(),'Partner contracts')!==false,'English partner controls render without automatic delivery');
